import json, requests
r=requests.get('https://rest.uniprot.org/uniprotkb/search',params={'query':'(protein_name:"OPCL1" OR gene:"OPCL1") AND organism_name:"Arabidopsis thaliana"','format':'json','size':10,'fields':'accession,protein_name,gene_names,organism_name,reviewed,organism_id'},timeout=30)
def names(pd):
    out={}
    rec=pd.get('recommendedName') or {}
    out['recommended']=(rec.get('fullName') or {}).get('value')
    out['alternatives']=[(a.get('fullName') or {}).get('value') for a in pd.get('alternativeNames') or []]
    out['submissions']=[(a.get('fullName') or {}).get('value') for a in pd.get('submissionNames') or []]
    return out
for it in r.json().get('results',[]):
    g=[]
    for gene in it.get('genes') or []:
        g.append({'primary':(gene.get('geneName') or {}).get('value'),'synonyms':[s.get('value') for s in gene.get('synonyms') or []],'orfNames':[s.get('value') for s in gene.get('orfNames') or []]})
    print(json.dumps({'acc':it.get('primaryAccession'),'entryType':it.get('entryType'),'names':names(it.get('proteinDescription') or {}),'genes':g,'tax':it.get('organism',{}).get('taxonId')}))
